<?php
declare(strict_types=1);
function exXml($s):string{return htmlspecialchars(preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/u','',(string)$s),ENT_XML1|ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function exColumns(array $rows,array $default=[]):array{$keys=$default;foreach($rows as $r)foreach(array_keys($r) as $k)if(!in_array($k,$keys,true))$keys[]=$k;return $keys;}
function exScalar($v){return is_array($v)||is_object($v)?json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):$v;}
function exNumeric(string $k):bool{return in_array($k,['id','project_id','usr_id','object_id','area_id','photo_id','version','area_m2','share','age','height','height_min','height_max','canopy_h_m','spread_m','lat_wgs84','lng_wgs84','x_sjtsk','y_sjtsk'],true)||preg_match('/^(dbh[1-4]_cm|girth[1-4]_cm|costs_tu[0-3])$/',$k)===1;}
function exXlsx(string $path,array $sheets):void{
 $zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('XLSX open');
 $types='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>';
 $work='<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>';$rels='<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';$i=0;
 foreach($sheets as $name=>$sheet){$i++;[$headers,$rows]=$sheet;$work.='<sheet name="'.exXml($name).'" sheetId="'.$i.'" r:id="rId'.$i.'"/>';$rels.='<Relationship Id="rId'.$i.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$i.'.xml"/>';$types.='<Override PartName="/xl/worksheets/sheet'.$i.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';
 $xml='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetData>';$rn=0;
 foreach([array_combine($headers,$headers),...$rows] as $r){$rn++;if($rn>1048576)throw new RuntimeException('Příliš mnoho řádků pro Excel.');$xml.='<row r="'.$rn.'">';$cn=0;foreach($headers as $key){$cn++;$n=$cn;$col='';while($n){$n--;$col=chr(65+$n%26).$col;$n=intdiv($n,26);}$v=exScalar($r[$key]??'');if(mb_strlen((string)$v)>32767)throw new RuntimeException('Hodnota ve sloupci '.$key.' překračuje limit buňky Excelu.');if($rn>1&&exNumeric($key)&&is_numeric($v)&&strlen(preg_replace('/[^0-9]/','',(string)$v))<=15)$xml.='<c r="'.$col.$rn.'"><v>'.exXml($v).'</v></c>';else $xml.='<c r="'.$col.$rn.'" t="inlineStr"><is><t xml:space="preserve">'.exXml($v).'</t></is></c>';}$xml.='</row>';}
 $xml.='</sheetData></worksheet>';$zip->addFromString('xl/worksheets/sheet'.$i.'.xml',$xml);
 }
 $zip->addFromString('[Content_Types].xml',$types.'</Types>');$zip->addFromString('xl/workbook.xml',$work.'</sheets></workbook>');$zip->addFromString('xl/_rels/workbook.xml.rels',$rels.'</Relationships>');$zip->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');if(!$zip->close())throw new RuntimeException('XLSX close');
}
function exQuote(string $s):string{return '"'.str_replace('"','""',$s).'"';}
function exGeometry(?array $g):?string{if(!$g)return null;$w="GP".chr(0).chr(1).pack('V',4326);if($g['type']==='Point')return $w.chr(1).pack('V',1).pack('e2',...$g['coordinates']);if($g['type']!=='Polygon')throw new RuntimeException('Nepodporovaná geometrie.');$w.=chr(1).pack('V',3).pack('V',count($g['coordinates']));foreach($g['coordinates'] as $ring){$w.=pack('V',count($ring));foreach($ring as $p)$w.=pack('e2',...$p);}return $w;}
function exGpkg(string $path,array $layers):void{
 $db=new SQLite3($path);$db->enableExceptions(true);$db->exec('PRAGMA application_id=1196444487; PRAGMA user_version=10300; PRAGMA encoding="UTF-8"; PRAGMA foreign_keys=ON; BEGIN;');
 $db->exec('CREATE TABLE gpkg_spatial_ref_sys (srs_name TEXT NOT NULL,srs_id INTEGER PRIMARY KEY,organization TEXT NOT NULL,organization_coordsys_id INTEGER NOT NULL,definition TEXT NOT NULL,description TEXT); CREATE TABLE gpkg_contents (table_name TEXT PRIMARY KEY,data_type TEXT NOT NULL,identifier TEXT UNIQUE,description TEXT DEFAULT \'\',last_change DATETIME NOT NULL DEFAULT (strftime(\'%Y-%m-%dT%H:%M:%fZ\',\'now\')),min_x DOUBLE,min_y DOUBLE,max_x DOUBLE,max_y DOUBLE,srs_id INTEGER,FOREIGN KEY(srs_id) REFERENCES gpkg_spatial_ref_sys(srs_id)); CREATE TABLE gpkg_geometry_columns (table_name TEXT NOT NULL,column_name TEXT NOT NULL,geometry_type_name TEXT NOT NULL,srs_id INTEGER NOT NULL,z TINYINT NOT NULL,m TINYINT NOT NULL,PRIMARY KEY(table_name,column_name),UNIQUE(table_name),FOREIGN KEY(table_name) REFERENCES gpkg_contents(table_name),FOREIGN KEY(srs_id) REFERENCES gpkg_spatial_ref_sys(srs_id));');
 $stmt=$db->prepare('INSERT INTO gpkg_spatial_ref_sys VALUES(?,?,?,?,?,?)');$wkt='GEOGCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],PRIMEM["Greenwich",0],UNIT["degree",0.0174532925199433],AUTHORITY["EPSG","4326"]]';foreach([['Undefined Cartesian',-1,'NONE',-1,'undefined',''],['Undefined geographic',0,'NONE',0,'undefined',''],['WGS 84',4326,'EPSG',4326,$wkt,'Longitude, latitude']] as $r){foreach($r as $i=>$v)$stmt->bindValue($i+1,$v,is_int($v)?SQLITE3_INTEGER:SQLITE3_TEXT);$stmt->execute();$stmt->reset();}
 foreach($layers as $name=>$layer){[$type,$rows,$geometries,$headers]=$layer;$headers=array_values(array_diff($headers,['id','geom']));$cols=array_map(fn($k)=>exQuote($k).(exNumeric($k)?' REAL':' TEXT'),$headers);$db->exec('CREATE TABLE '.exQuote($name).' (fid INTEGER PRIMARY KEY,geom '.($type==='POINT'?'POINT':'POLYGON').($cols?','.implode(',',$cols):'').')');$s=$db->prepare('INSERT INTO gpkg_contents(table_name,data_type,identifier,srs_id) VALUES(?,\'features\',?,4326)');$s->bindValue(1,$name);$s->bindValue(2,$name);$s->execute();$s=$db->prepare('INSERT INTO gpkg_geometry_columns VALUES(?,\'geom\',?,4326,0,0)');$s->bindValue(1,$name);$s->bindValue(2,$type);$s->execute();
 $s=$db->prepare('INSERT INTO '.exQuote($name).' VALUES('.implode(',',array_fill(0,2+count($headers),'?')).')');foreach($rows as $i=>$row){$s->bindValue(1,$i+1,SQLITE3_INTEGER);$g=exGeometry($geometries[$i]??null);$s->bindValue(2,$g,$g===null?SQLITE3_NULL:SQLITE3_BLOB);foreach($headers as $j=>$k){$v=exScalar($row[$k]??null);$s->bindValue($j+3,$v,$v===null?SQLITE3_NULL:(exNumeric($k)&&is_numeric($v)?SQLITE3_FLOAT:SQLITE3_TEXT));}$s->execute();$s->reset();}}
 $db->exec('COMMIT');$db->close();
}
